"""Build/run the local vertex numeric check; generated C and binary stay under build_fpk1."""
import sys
sys.dont_write_bytecode = True
import os, shlex, subprocess
from pathlib import Path
REPO=next(p for p in Path(__file__).resolve().parents if (p/'hw/arm/fpk1.c').is_file())
ROOT=REPO/'build_fpk1/research-artifacts/cgdrv-experiment/gear'
ROOT.mkdir(parents=True,exist_ok=True)
C_SOURCE = '/* Local debugging: transform feedback versus an independently simplified model. */\n#include <EGL/egl.h>\n#include <EGL/eglext.h>\n#include <GLES3/gl3.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <math.h>\n#include <string.h>\nstatic GLuint shader(GLenum type,const char *source){GLuint s=glCreateShader(type);glShaderSource(s,1,&source,NULL);glCompileShader(s);GLint ok;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[8192];glGetShaderInfoLog(s,sizeof(log),NULL,log);fprintf(stderr,"%s\\n",log);exit(2);}return s;}\nstatic float fract(float x){return x-floorf(x);}\nstatic void uniform(GLuint p,const char *name,float value){GLint loc=glGetUniformLocation(p,name);if(loc<0){fprintf(stderr,"missing uniform %s\\n",name);exit(2);}glUniform1f(loc,value);}\nint main(int argc,char **argv){\n if(argc!=2)return 2;FILE *f=fopen(argv[1],"rb");if(!f)return 2;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);char *source=calloc(n+1,1);fread(source,1,n,f);fclose(f);\n EGLDisplay d=eglGetPlatformDisplay(EGL_PLATFORM_SURFACELESS_MESA,NULL,NULL);EGLint maj,min,count;EGLConfig cfg;\n EGLint a[]={EGL_SURFACE_TYPE,EGL_PBUFFER_BIT,EGL_RENDERABLE_TYPE,EGL_OPENGL_ES3_BIT,EGL_NONE};\n EGLint pb[]={EGL_WIDTH,16,EGL_HEIGHT,16,EGL_NONE},ca[]={EGL_CONTEXT_CLIENT_VERSION,3,EGL_NONE};\n if(!eglInitialize(d,&maj,&min)||!eglChooseConfig(d,a,&cfg,1,&count)||!count)return 2;\n EGLSurface surf=eglCreatePbufferSurface(d,cfg,pb);EGLContext ctx=eglCreateContext(d,cfg,EGL_NO_CONTEXT,ca);if(!eglMakeCurrent(d,surf,surf,ctx))return 2;\n GLuint p=glCreateProgram();glAttachShader(p,shader(GL_VERTEX_SHADER,source));glAttachShader(p,shader(GL_FRAGMENT_SHADER,"precision mediump float;void main(){gl_FragColor=vec4(1.0);}"));glBindAttribLocation(p,0,"kzPosition");glBindAttribLocation(p,1,"kzTextureCoordinate0");\n const char *vary[]={"gl_Position","values"};glTransformFeedbackVaryings(p,2,vary,GL_INTERLEAVED_ATTRIBS);glLinkProgram(p);GLint linked;glGetProgramiv(p,GL_LINK_STATUS,&linked);if(!linked){char log[8192];glGetProgramInfoLog(p,sizeof(log),NULL,log);fprintf(stderr,"%s\\n",log);return 2;}glUseProgram(p);\n GLuint in,out;glGenBuffers(1,&in);glGenBuffers(1,&out);glBindBuffer(GL_ARRAY_BUFFER,in);glBufferData(GL_ARRAY_BUFFER,16*5*sizeof(float),NULL,GL_DYNAMIC_DRAW);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,5*sizeof(float),0);glVertexAttribPointer(1,2,GL_FLOAT,GL_FALSE,5*sizeof(float),(void *)(3*sizeof(float)));glEnableVertexAttribArray(0);glEnableVertexAttribArray(1);\n glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,out);glBufferData(GL_TRANSFORM_FEEDBACK_BUFFER,16*7*sizeof(float),NULL,GL_DYNAMIC_READ);glBindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER,0,out);glEnable(GL_RASTERIZER_DISCARD);\n float matrix[]={1.1f,.2f,.1f,.03f,-.1f,.8f,.15f,.04f,.12f,.09f,1.2f,.06f,3.f,-2.f,.4f,1.f};\n glUniformMatrix4fv(glGetUniformLocation(p,"kzProjectionCameraWorldMatrix"),1,GL_FALSE,matrix);\n float worst=0;int checked=0;\n for(int c=0;c<120;c++){\n  float stage=(float[]){0,1,.37f}[c%3],id=(c/3)%2?14:3,pos=(float[]){-.2f,-.1f,0,.1f,.2f}[(c/6)%5],accept=(c/30)%2?1:0;\n  float width=(c%2)?11.f:12.f,height=(c%5)?21.f:22.f,cols=(c%7)+1,opacity=.37f,state=.8f;\n  uniform(p,"gearStageBig",stage);uniform(p,"gear_charID",id);uniform(p,"gear_char_pos",pos);uniform(p,"gear_recc_on_accept",accept);uniform(p,"gear_char_width",width);uniform(p,"gear_char_height",height);uniform(p,"gear_atlas_cols",cols);uniform(p,"LayerRenderOpacity",opacity);uniform(p,"gear_recc_state",state);\n  float input[16*5];for(int i=0;i<16;i++){input[5*i]=(i-8)*1.27f;input[5*i+1]=(i-3)*.81f;input[5*i+2]=i*.07f;input[5*i+3]=i*.09f;input[5*i+4]=i*.13f;}\n  glBindBuffer(GL_ARRAY_BUFFER,in);glBufferSubData(GL_ARRAY_BUFFER,0,sizeof(input),input);glBeginTransformFeedback(GL_POINTS);glDrawArrays(GL_POINTS,0,16);glEndTransformFeedback();glFinish();glBindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,out);float *actual=glMapBufferRange(GL_TRANSFORM_FEEDBACK_BUFFER,0,16*7*sizeof(float),GL_MAP_READ_BIT);if(!actual)return 2;\n  for(int i=0;i<16;i++){\n   float snap=floorf(stage)+floorf(1-stage),x=input[5*i],y=input[5*i+1];\n   x+=(id==14)?-(40-10*stage):(39-12*stage)*(1-accept)*pos;\n   x-=width*.5f+fract(width*.5f)*snap;y-=height*.5f+fract(height*.5f)*snap;\n   float expected[7];for(int j=0;j<4;j++)expected[j]=matrix[j]*x+matrix[4+j]*y+matrix[8+j]*input[5*i+2]+matrix[12+j];\n   float clamped=fminf(.1f,fmaxf(-.1f,pos));expected[4]=(input[5*i+3]-floorf(-clamped))/cols;expected[5]=input[5*i+4]*.5f;expected[6]=state*opacity;\n   for(int j=0;j<7;j++){float err=fabsf(actual[i*7+j]-expected[j]);if(err>worst)worst=err;if(err>2e-4f){fprintf(stderr,"case %d vertex %d component %d actual %.9g expected %.9g error %.9g\\n",c,i,j,actual[i*7+j],expected[j],err);return 1;}}\n   checked++;\n  }\n  glUnmapBuffer(GL_TRANSFORM_FEEDBACK_BUFFER);\n }\n if(glGetError()!=GL_NO_ERROR)return 2;\n printf("{\\"vertices_checked\\":%d,\\"parameter_cases\\":120,\\"max_abs_error\\":%.9g,\\"passed\\":true}\\n",checked,worst);return 0;\n}\n'
source=ROOT/'check_vertex.c'
source.write_text(C_SOURCE)
flags=shlex.split(subprocess.check_output(['pkg-config','--cflags','--libs','egl','glesv2'],text=True))
subprocess.run([os.environ.get('CC','cc'),'-O2',str(source),'-o',str(ROOT/'check_vertex'),*flags],check=True)
result=subprocess.run([str(ROOT/'check_vertex'),str(ROOT/'vertex.glsl')],check=True,capture_output=True,text=True)
(ROOT/'vertex-numeric-check.json').write_text(result.stdout)
print(result.stdout,end='')
